import{_ as i,l,o as e,c as r,v as o,p as s,x as t,d as p,i as E,S as m}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"多重检验","description":"","frontmatter":{"title":"多重检验","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/multiple-testing-econ.md","filePath":"econ/multiple-testing-econ.md","lastUpdated":1789023840000}'),c={name:"econ/multiple-testing-econ.md"};function d(h,a,B,A,_,u){const n=l("Mermaid");return e(),r("div",null,[a[1]||(a[1]=o('<h1 id="多重检验" tabindex="-1">多重检验 <a class="header-anchor" href="#多重检验" aria-label="Permalink to &quot;多重检验&quot;">​</a></h1><div class="epigraph"><p>二十个系数各用名义 5%，至少一个假阳性的概率远高于 5%。Holm 管族错误率；Benjamini–Hochberg 管假发现比例——改的是拒绝规则，不是单个 $p$ 的定义。</p><footer>—— Holm, Scandinavian Journal of Statistics 1979；Benjamini and Hochberg, JRSS-B 1995；对照 Romano and Wolf 逐步法；Angrist and Pischke</footer></div><p><a href="/econ/bootstrap-econ">上一课</a>给单个统计量一套可行的抽样分布：三明治或重抽样。本课缺口是：一张表里十个滞后、五个子样本、二十个行业，或扫描一篮子政策变量——即使每一个 \\(t\\) 都算对了，<strong>同时</strong>看它们仍会把假阳性堆出来。后课<a href="/econ/inference-robust-cluster">稳健、聚类与多重检验</a>把推断工具收束成检查清单；本课只加「许多原假设一起测」这一块。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(m\\) 个原假设，各用水平 \\(\\alpha\\)。若独立且全真，至少一次错拒的概率 \\(1-(1-\\alpha)^m\\)， \\(m=20\\)、\\(\\alpha=0.05\\) 时已超过六成。族错误率 FWER 是这句话的概率；FDR 是「拒绝里假发现所占比例」的期望。缺口不是再估一次 SE，而是：研究者实际做了多少次选择——包括没写进正文、只把「最显著」留下来的那些。规格搜索、子样本循环、先看图再决定分组，都是隐式 \\(m\\)。</p><p>预注册一个主结果，是设计上把 \\(m\\) 压回 1；校正公式是事后补救。两件事不互相替代。</p><h3 id="只报显著的那个就是多重检验" tabindex="-1">只报显著的那个就是多重检验 <a class="header-anchor" href="#只报显著的那个就是多重检验" aria-label="Permalink to &quot;只报显著的那个就是多重检验&quot;">​</a></h3><p>正文里只出现一个 \\(p\\lt 0.05\\) 的系数，附录里躺着十九个不显著的孪生规格，读者按 \\(m=1\\) 来读，名义水平已经坏了。这不是诚实问题的修辞，是样本空间没写全。机器学习里的 snooping 同源：特征在同一张表上挑完再检验，要用样本外或正交化，不能靠「最后只报一个」。</p><p><span class="marginnote">Angrist–Pischke 的实用划分：一个 primary outcome，其余当 robustness 并标明探索。FDR 适合探索清单；确认性研究更常保 FWER 或干脆只测一个。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Bonferroni：每个检验用 \\(\\alpha/m\\)，简单、常过严。Holm：将 \\(p\\) 排序 \\(p_{(1)}\\le\\cdots\\le p_{(m)}\\)，找最小 \\(k\\) 使 \\(p_{(k)}\\gt \\alpha/(m-k+1)\\)，拒绝更小的那些——逐步、仍控 FWER，功效通常高于 Bonferroni。Benjamini–Hochberg：找最大 \\(k\\) 使 \\(p_{(k)}\\le k\\alpha/m\\)，拒绝 \\(1,\\ldots,k\\)，在独立或正依赖下控 FDR。检验相关时，BH 仍常用；FWER 方法可能更保守。Westfall–Young 一类 bootstrap 可同时吃进相关与小样本，装置接上一课，细节不在此展开。</p>',11)),(e(),s(m,null,{default:t(()=>[E(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BOOT%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E5%8D%95%E4%B8%AA%E7%BB%9F%E8%AE%A1%E9%87%8F%E7%9A%84%E5%88%86%E5%B8%83%22%5D%20--%3E%20M%5B%22m%20%E4%B8%AA%E5%8E%9F%E5%81%87%E8%AE%BE%22%5D%0A%20%20M%20--%3E%20FWER%5B%22FWER%3A%20Bonferroni%20%2F%20Holm%22%5D%0A%20%20M%20--%3E%20FDR%5B%22FDR%3A%20Benjamini%E2%80%93Hochberg%22%5D%0A%20%20FWER%20--%3E%20CONF%5B%22%E7%A1%AE%E8%AE%A4%E6%80%A7%E3%80%81%E4%B8%BB%E7%BB%93%E6%9E%9C%22%5D%0A%20%20FDR%20--%3E%20EXPL%5B%22%E6%8E%A2%E7%B4%A2%E6%B8%85%E5%8D%95%E3%80%81%E4%BF%9D%E7%95%99%E5%8A%9F%E6%95%88%22%5D%0A%20%20M%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E4%B8%8E%E7%A8%B3%E5%81%A5%E3%80%81%E8%81%9A%E7%B1%BB%E6%94%B6%E6%9D%9F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>主结果与探索结果分开写：前者按 \\(m=1\\)（或预注册的小数目）报；后者报校正后的 \\(q\\) 值或明确说未校正。不要用校正当许可，去扫遍所有交互。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>单个 \\(p\\) 仍是「这个假设下更极端的概率」。多重检验改的是阈值：你愿意在一整族里冒多大的错拒风险。FWER 把「至少一个错」当事件，适合监管或单一政策结论；FDR 允许错几个，换更多真发现，适合描述性扫描。隐式多重检验之所以毒，是因为阈值还按 \\(m=1\\) 算，而选择已经发生。</p><p>与聚类、bootstrap 正交：先把每一个检验的 \\(p\\) 算对（依赖结构、有限样本），再对这组 \\(p\\) 做 Holm/BH。顺序不能倒成「先 BH 再随便 cluster」。</p><p><span class="marginnote">Romano–Wolf 逐步法在功效与 FWER 之间折中，常用于多结果的实验。本课以 Holm 与 BH 为默认语言，后课收束时可以点名它们。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 BH 读成「可以随便挖」。也不处理序贯分析、可选停止的全部贝叶斯决策。相关检验的精确 FWER 控制可以更紧，那是专门文献。量化栏因子动物园是多重检验的经典现场，本课不重做那些表，以免吞并资产定价。下一课把 White、聚类、本课校正放回同一张检查单，并接到机器学习因果估计。</p><p>后课默认：报告估计量时写清测了多少个假设；主结论不靠扫描。聚类与 bootstrap 解决的是单个 \\(p\\) 的分母，多重检验解决的是多少个 \\(p\\) 被一起读。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多假设同时读，名义 \\(\\alpha\\) 不再是一族的错误率。</li><li>Holm 控 FWER；Benjamini–Hochberg 控 FDR。</li><li>只展示显著规格，等于隐瞒 \\(m\\)。</li><li>预注册主结果优于事后校正，校正是补救。</li><li>与稳健 SE、聚类、bootstrap 叠加，不互相替代。</li><li>出处：Holm 1979；Benjamini and Hochberg 1995；Romano and Wolf；Angrist and Pischke。</li></ul>',10))])}const b=i(c,[["render",d]]);export{F as __pageData,b as default};
